import {test} from 'node:test';
import assert from 'node:assert/strict';
import {BASE,REF,validate,reportCheck,browserCheck} from './scale-authoring-scope.mjs';
const fixture=()=>{const entries=Array.from({length:85},(_,i)=>({file:`file${i}`,before:'a'.repeat(40),after:'b'.repeat(40),beforeMode:'100644',afterMode:'100644',status:'M'}));return {entries,manifest:{base:BASE,scope:'scale-authoring-feedback-20261021',files:Object.fromEntries(entries.map(e=>[e.file,{before:e.before,after:e.after}]))},context:{event:'push',ref:REF,head:'c'.repeat(40)}}};
test('exact reviewed candidate accepts but is not merge qualification',()=>{const f=fixture();assert.equal(validate(f.entries,f.manifest,f.context).mergeQualified,false)});
for(const scenario of ['work-branch','pull-request','unknown','missing','changed','base','mode','delete'])test('fail closed: '+scenario,()=>{const f=fixture();if(scenario==='work-branch')f.context.ref='refs/heads/work/scale-authoring-feedback-20261021';if(scenario==='pull-request')f.context.event='pull_request';if(scenario==='unknown')f.entries[0].file='unknown';if(scenario==='missing')f.entries.pop();if(scenario==='changed')f.entries[0].after='d'.repeat(40);if(scenario==='base')f.entries[0].before='d'.repeat(40);if(scenario==='mode')f.entries[0].afterMode='120000';if(scenario==='delete')f.entries[0].status='D';assert.throws(()=>validate(f.entries,f.manifest,f.context))});
test('test reporter requires real passed assertions and no failures/skips',()=>{const r={success:true,numPassedTests:1,numFailedTests:0,numFailedTestSuites:0,numPendingTests:0};assert.equal(reportCheck(r).passed,1);for(const bad of [{...r,numPassedTests:0},{...r,success:false},{...r,numFailedTests:1},{...r,numPendingTests:1}])assert.throws(()=>reportCheck(bad));assert.equal(reportCheck({...r,numPendingTests:8},{allowFiltered:true}).filtered,8)});

test('browser evidence fails closed on empty, failed, missing or wrong-head results',()=>{for(const bad of [{},{status:'FAIL'},{status:'PASS',sourceCommit:'wrong'},{status:'PASS',sourceCommit:'abc',checks:[]}])assert.throws(()=>browserCheck(bad,'abc'))});
test('browser validator accepts complete synthetic validator fixture and rejects one omitted screenshot',()=>{const checks=['training-editor-native','training-stable-item-operations','training-quality-roundtrip','training-published','training-final-report-image','survey-editor-native','survey-quality-roundtrip','survey-published','survey-final-report-image','survey-raw-quality-export','training-report-image-denies-other-user','survey-report-image-denies-missing-proof','desktop-mobile-layout'];const r={measurementPublication:{status:'PUBLISHED',currentRevisionBound:true,frozenReleaseMatches:true},journeySources:{training:{mode:'executed',runId:1,sourceHead:'abc'},survey:{mode:'executed',runId:1,sourceHead:'abc'}},participantAnswers:[{name:'training',answerCount:3,matchesFinalSnapshot:true},{name:'survey',answerCount:3,matchesFinalSnapshot:true}],status:'PASS',sourceCommit:'abc',checks,blockedExternalRequests:0,browserErrors:[],screenshots:[390,768,1440].flatMap(width=>['training-editor','training-report','survey-editor','survey-report'].map(name=>({name,width,file:`${name}-${width}.png`}))),layoutChecks:['training-editor','training-report','survey-editor','survey-report'].flatMap(name=>[390,768,1440].map(width=>({name,width,overflow:false}))),accessibility:['training-editor','training-report','survey-editor','survey-report'].map(name=>({name,passes:1,violations:[]})),export:{format:'RAW_WAVE',rowCount:3,downloadedFiles:3},imageAuthorization:['training-other-user','survey-missing-proof'].map(name=>({name,positiveStatus:200,deniedStatus:404,deniedImage:false,deniedLength:0}))};assert.equal(browserCheck(r,'abc').checks,13);const reused={...r,journeySources:{...r.journeySources,training:{"mode":"reused","runId":39571934879,"sourceHead":"7daa3ad8cb0fb9597303a2ef3e1c28c3209dd548","reportSha256":"d7511d708d7b12dc643f02061b526da9b9bb61292ddc5172a7a1300bc95ad3e3","originalStatus":"FAIL","screenshotHashes":{"training-editor-1440.png":"a1f620b475d1af6b7bb6f7219caedcf7224e57c27178727d72ed4247aa874c79","training-editor-390.png":"fcc5cf3e25f9f3fed748156a6dd289e27822872850e6275c4cc65d90c1937057","training-editor-768.png":"1baa0b62047a51aec1882c9bbd78d171b308b815832a8715e92088735dfb2e5c","training-report-1440.png":"a7400392843a26c0d574d5d6970498bef087f1d08d5fc8b3478b43b4308df108","training-report-390.png":"62e73fa19b7d4c7cf30d1bc6f900d4dc3b03d913885854aa3e8a229dda1ffd73","training-report-768.png":"03fc1e967aedf3952b7e973ec0ba01787ce9cc3453ced7b94d24c8847ff0664e"}}}};assert.equal(browserCheck(reused,'abc',1).checks,13);for(const key of ['runId','sourceHead','reportSha256','originalStatus','screenshotHashes'])assert.throws(()=>browserCheck({...reused,journeySources:{...reused.journeySources,training:{...reused.journeySources.training,[key]:null}}},'abc',1));assert.throws(()=>browserCheck(reused,'abc',2));assert.throws(()=>browserCheck({...r,screenshots:r.screenshots.slice(1)},'abc'));for(const bad of [{...r,measurementPublication:undefined},{...r,measurementPublication:{...r.measurementPublication,currentRevisionBound:false}},{...r,measurementPublication:{...r.measurementPublication,frozenReleaseMatches:false}},{...r,journeySources:undefined},{...r,journeySources:{...r.journeySources,training:{mode:'reused'}}},{...r,journeySources:{...r.journeySources,survey:{mode:'executed',runId:1,sourceHead:'wrong'}}},{...r,participantAnswers:[]},{...r,participantAnswers:r.participantAnswers.slice(1)},{...r,participantAnswers:r.participantAnswers.map(x=>({...x,matchesFinalSnapshot:false}))},{...r,participantAnswers:r.participantAnswers.map(x=>({...x,answerCount:2}))},{...r,export:{...r.export,downloadedFiles:2}},{...r,export:{...r.export,format:'wrong'}},{...r,imageAuthorization:r.imageAuthorization.slice(1)},...['positiveStatus','deniedStatus','deniedImage','deniedLength'].map(key=>({...r,imageAuthorization:r.imageAuthorization.map(x=>({...x,[key]:key==='deniedImage'?true:-1}))}))])assert.throws(()=>browserCheck(bad,'abc'));for(const layoutChecks of [r.layoutChecks.slice(1),r.layoutChecks.map((x,i)=>i?x:{...x,overflow:true}),r.layoutChecks.map((x,i)=>i?x:{...x,overflow:undefined}),r.layoutChecks.map((x,i)=>i?x:{...x,name:'wrong'})])assert.throws(()=>browserCheck({...r,layoutChecks},'abc'));assert.throws(()=>browserCheck({...r,accessibility:[{passes:1,violations:[{id:'color-contrast'}]},...r.accessibility.slice(1)]},'abc'))});
